#include <Arduino.h>
#include "pins.h"
#include <NewPing.h>
#include <Adafruit_NeoPixel.h>

// Ramp PWM up gradually so only one motor is ever near stall current (see power budget).
void driveRamp(uint8_t pin, uint8_t target) {
  for (uint8_t d = 0; d < target; d += 5) { analogWrite(pin, d); delay(4); }
  analogWrite(pin, target);
}

void setup() {
  Serial.begin(115200);
  pinMode(DISTANCE_SENSOR_1_ECHO, INPUT);
  pinMode(DISTANCE_SENSOR_1_TRIG, OUTPUT);
  pinMode(DISTANCE_SENSOR_2_ECHO, INPUT);
  pinMode(DISTANCE_SENSOR_2_TRIG, OUTPUT);
  pinMode(LED_STRIP_DIN, OUTPUT);
  pinMode(MOTOR_DRIVER_AIN1, OUTPUT);
  pinMode(MOTOR_DRIVER_AIN2, OUTPUT);
  pinMode(MOTOR_DRIVER_BIN1, OUTPUT);
  pinMode(MOTOR_DRIVER_BIN2, OUTPUT);
  pinMode(MOTOR_DRIVER_2_AIN1, OUTPUT);
  pinMode(MOTOR_DRIVER_2_AIN2, OUTPUT);
  pinMode(MOTOR_DRIVER_2_BIN1, OUTPUT);
  pinMode(MOTOR_DRIVER_2_BIN2, OUTPUT);
  Serial.println("boot ok");
}

void loop() {
  // driveRamp(MOTOR_DRIVER_AIN1, 200); // soft-start keeps the battery peak within budget
  delay(1000);
}
